module.exports = {
  webpack: (config, { dev, isServer }) => {
    // SVG loader configuration
    config.module.rules.push({
      test: /\.svg /,
      use: [
        {
          loader: '@svgr/webpack',
          options: {
            prettier: false,
            svgo: false,
            svgoConfig: {
              plugins: [{ removeViewBox: false }],
            },
            titleProp: true,
            ref: true,
          },
        },
      ],
    })

    // GLSL shader loader
    config.module.rules.push({
      test: /\.(glsl|vs|fs|vert|frag) /,
      use: ['raw-loader', 'glslify-loader'],
    })

    // Worker loader
    config.module.rules.push({
      test: /\.worker\.js /,
      use: { loader: 'worker-loader' },
    })

    // Custom CSS processing
    config.module.rules.push({
      test: /\.scss /,
      use: [
        'style-loader',
        {
          loader: 'css-loader',
          options: {
            modules: {
              localIdentName: dev 
                ? '[name]__[local]--[hash:base64:5]' 
                : '[hash:base64:8]',
            },
          },
        },
        'sass-loader',
      ],
    })

    return config
  },
}
