class BankAccount {
    // Private fields (ES2022)
    #accountNumber;
    #balance;
    #transactionHistory;
    
    constructor(accountNumber, initialBalance) {
        this.#accountNumber = accountNumber;
        this.#balance = initialBalance;
        this.#transactionHistory = [];
    }
    
    // Public getter for account number
    get accountNumber() {
        return this.#accountNumber;
    }
    
    // Public getter for balance
    get balance() {
        return this.#balance;
    }
    
    // Public method with validation
    deposit(amount) {
        if (!this.#validateAmount(amount)) {
            throw new Error("Invalid deposit amount");
        }
        
        this.#balance += amount;
        this.#recordTransaction("DEPOSIT", amount);
        return this.#balance;
    }
    
    // Public method with business logic
    withdraw(amount) {
        if (!this.#validateAmount(amount)) {
            throw new Error("Invalid withdrawal amount");
        }
        if (amount > this.#balance) {
            throw new Error("Insufficient funds");
        }
        
        this.#balance -= amount;
        this.#recordTransaction("WITHDRAWAL", amount);
        return this.#balance;
    }
    
    // Public method returning copy of history
    getTransactionHistory() {
        return [...this.#transactionHistory];
    }
    
    // Private method for validation
    #validateAmount(amount) {
        return typeof amount === 'number' && amount > 0;
    }
    
    // Private method for recording transactions
    #recordTransaction(type, amount) {
        this.#transactionHistory.push({
            type,
            amount,
            timestamp: new Date(),
            balanceAfter: this.#balance
        });
    }
}

// Alternative using closures for information hiding (pre-ES2022)
function createBankAccount(accountNumber, initialBalance) {
    // Private variables in closure
    let balance = initialBalance;
    let transactionHistory = [];
    
    function recordTransaction(type, amount) {
        transactionHistory.push({
            type,
            amount,
            timestamp: new Date(),
            balanceAfter: balance
        });
    }
    
    function validateAmount(amount) {
        return typeof amount === 'number' && amount > 0;
    }
    
    // Return public interface
    return {
        get accountNumber() { return accountNumber; },
        get balance() { return balance; },
        
        deposit(amount) {
            if (!validateAmount(amount)) {
                throw new Error("Invalid deposit amount");
            }
            balance += amount;
            recordTransaction("DEPOSIT", amount);
            return balance;
        },
        
        withdraw(amount) {
            if (!validateAmount(amount)) {
                throw new Error("Invalid withdrawal amount");
            }
            if (amount > balance) {
                throw new Error("Insufficient funds");
            }
            balance -= amount;
            recordTransaction("WITHDRAWAL", amount);
            return balance;
        },
        
        getTransactionHistory() {
            return [...transactionHistory];
        }
    };
}

// Usage
